-- 00039_more_programs.sql
--
-- Eight more training programmes. Five fill the Athleticism group, which had
-- none: onboarding sends players who pick on-ball defence, first step speed or
-- ankle and knee durability to the athleticism programmes (src/lib/recommend.ts),
-- and until now that list was empty. The other three fill gaps in shooting,
-- ball handling and getting back into training after time off.
--
-- NOTE ON STYLE: no apostrophes in the comments of this file, for the reason
-- given at the top of 00035. Keep it apostrophe-free. The only apostrophes in
-- the string values are the doubled ones inside two exercise names.
--
-- Same shape as the programmes in 00014: drills come from 00013, exercises
-- from seed.sql and 00011, lessons from seed.sql and 00012, and tests from the
-- performance_tests check in 00003. __tests__/programContent.test.ts reads this
-- file and fails if any of those references does not exist.
--
-- Built for players from 13 up. Strength work is bodyweight or light load with
-- reps left in the tank, nothing to failure and no max lifts, and there are no
-- barbell lifts or depth jumps. Speed and Agility points younger or newer
-- players to Basketball Strength Foundations first.
--
-- Safe to re-run: programmes skip existing slugs and days skip existing
-- (programme, week, day) pairs, as in 00014. Editing a row here and running the
-- file again does not change a row that already exists.

-- =============================================================================
-- 1. PROGRAMMES
-- =============================================================================
INSERT INTO public.training_programs (slug, name, description, goal, level, position, weeks, sessions_per_week, season, display_order) VALUES
  ('strength-foundations', 'Basketball Strength Foundations', 'Your first strength plan, built for players from 13 up. Four weeks of bodyweight and light-load technique for squatting, hinging, lunging, pushing, pulling, core and landing safely, in three short sessions a week. Every set stops with two or three good reps left: nothing to failure and no max lifts. Broad jump and lane agility tests in week 1 and week 4 show your progress.', 'athleticism', 'beginner', 'any', 4, 3, 'any', 11),
  ('speed-and-agility', 'Speed and Agility', 'Six weeks to a quicker first step, faster slides and sharper cuts. Acceleration, deceleration and change-of-direction work with the plyometrics and single-leg strength behind them, in short sessions where every rep is done fresh and fast. Test the 5-10-5, lane agility and 3/4 court sprint in week 1, then taper and retest in week 6.', 'athleticism', 'intermediate', 'any', 6, 3, 'off_season', 12),
  ('lockdown-defender', 'Lockdown Defender', 'Become the defender your coach puts on the best player. Four weeks of stance, slides, closeouts, help and recover and contesting without fouling, with the lateral strength and stamina behind them. Lane agility test in week 1 and week 4 and a weekly lesson on team defense. Most drills work solo, and every partner drill comes with a solo swap.', 'athleticism', 'intermediate', 'any', 4, 3, 'any', 13),
  ('game-shape-conditioning', 'Game-Shape Conditioning', 'Get fit enough to play hard for a whole game. Six weeks of basketball conditioning before the season: repeat sprints, defensive slide intervals, full-court layups and free throws on tired legs, with rest that shrinks as you get fitter. A timed suicide and 3/4 court sprint at the start, then a taper before you retest in week 6.', 'athleticism', 'intermediate', 'any', 6, 3, 'off_season', 14),
  ('injury-prevention-mobility', 'Injury Prevention and Mobility', 'Short sessions to help keep your ankles, knees and hips healthy through a long season. Balance and ankle strength, knee-friendly leg work, hip mobility and safe landings, 25 to 30 minutes three times a week, easy to fit around team practice. A balance check in week 1 and week 4 shows your progress. This is not rehab: if something already hurts, see a physio or doctor first.', 'athleticism', 'all', 'any', 4, 3, 'any', 15),
  ('shot-creator', 'Shot Creator: Off-the-Dribble Scoring', 'Create your own shot. Five weeks of moves that lead straight into a score: one and two dribble pull-ups, hesitations, step-backs and side-steps, floaters and finishes after a change of pace. Each week adds a counter, every session has a make target to beat, and weekly lessons cover reading the defense.', 'ball_handling', 'intermediate', 'any', 5, 3, 'any', 16),
  ('clutch-free-throws', 'Free Throws and Clutch Shooting', 'Make them when the game is on the line. Four weeks to build one free throw routine you trust, then test it on tired legs, on a pressure ladder and in last-shot scenarios. Short sessions that fit before or after practice, a 50-shot baseline in week 1 to beat in week 4, and lessons on the mental game and late-game situations.', 'shooting', 'all', 'any', 4, 3, 'any', 17),
  ('back-from-a-break', 'Back From a Break', 'Two weeks to get your touch, legs and lungs back after time off, whether that was a holiday, exams or the end of the season. Short sessions that build back up without overdoing it, so you are ready to start a full program in week 3. Not for coming back from an injury: get the all-clear from a physio or doctor first.', 'complete', 'all', 'any', 2, 3, 'any', 18)
ON CONFLICT (slug) DO NOTHING;

-- =============================================================================
-- 2. PROGRAMME DAYS
-- =============================================================================
INSERT INTO public.program_days (program_id, week, day, title, focus, estimated_minutes, items)
SELECT p.id, v.week, v.day, v.title, v.focus, v.estimated_minutes, v.items::jsonb
FROM (VALUES
  ('strength-foundations', 1, 1, 'Baseline and the Squat', 'Week 1 (Learn the moves): test day, then learn the squat', 40, '[{"type":"note","text":"Warm up 8 minutes first: easy jog, skips, side shuffles and leg swings."},{"type":"test","test_type":"standing_broad_jump"},{"type":"test","test_type":"lane_agility"},{"type":"note","text":"Every set in this program ends with 2 or 3 good reps left in the tank. If your form breaks, the set is over."},{"type":"exercise","name":"Goblet Squat","sets":2,"reps":"8, holding a ball at your chest"},{"type":"exercise","name":"Glute Bridge","sets":2,"reps":"10"},{"type":"exercise","name":"Bird Dog","sets":2,"reps":"6 each side"},{"type":"exercise","name":"Front Plank","sets":2,"reps":"20 sec"}]'),
  ('strength-foundations', 1, 2, 'Push, Pull and Land', 'Week 1 (Learn the moves): upper body and quiet landings', 30, '[{"type":"exercise","name":"Push-Ups (Tempo)","sets":2,"reps":"6, hands on a bench if needed"},{"type":"exercise","name":"Inverted Row","sets":2,"reps":"8, under a low bar"},{"type":"exercise","name":"Snap Downs","sets":2,"reps":"5"},{"type":"drill","slug":"jump-stop-landings"},{"type":"exercise","name":"Side Plank","sets":2,"reps":"15 sec each"},{"type":"note","text":"Quiet landings mean soft knees and hips. A loud landing means you landed stiff."}]'),
  ('strength-foundations', 1, 3, 'Hinge, Lunge and Balance', 'Week 1 (Learn the moves): hip hinge, split stance and balance', 35, '[{"type":"note","text":"No dumbbells? A backpack with a few books in it works for every loaded move in this program."},{"type":"exercise","name":"Dumbbell Romanian Deadlift","sets":2,"reps":"8, light"},{"type":"exercise","name":"Reverse Lunge","sets":2,"reps":"6 each leg"},{"type":"exercise","name":"Single-Leg Balance Reach","sets":2,"reps":"6 each leg"},{"type":"exercise","name":"Pogo Hops","sets":2,"reps":"10"},{"type":"exercise","name":"Dead Bug (Contralateral)","sets":2,"reps":"6 each side"},{"type":"exercise","name":"Couch Stretch (Hip Flexor / Quad)","sets":2,"reps":"45 sec each"}]'),
  ('strength-foundations', 2, 1, 'Squat and Core', 'Week 2 (Learn the moves): same moves, a few more reps', 35, '[{"type":"exercise","name":"Goblet Squat","sets":3,"reps":"8"},{"type":"exercise","name":"Glute Bridge","sets":3,"reps":"12"},{"type":"exercise","name":"Lateral Lunge","sets":2,"reps":"6 each side"},{"type":"exercise","name":"Bird Dog","sets":2,"reps":"8 each side"},{"type":"exercise","name":"Front Plank","sets":2,"reps":"25 sec"},{"type":"exercise","name":"Ankle Dorsiflexion Knee-to-Wall","sets":2,"reps":"8 each"}]'),
  ('strength-foundations', 2, 2, 'Push, Pull and Land', 'Week 2 (Learn the moves): upper body and quiet landings', 35, '[{"type":"exercise","name":"Push-Ups (Tempo)","sets":3,"reps":"6"},{"type":"exercise","name":"Inverted Row","sets":3,"reps":"8"},{"type":"exercise","name":"Snap Downs","sets":3,"reps":"5"},{"type":"exercise","name":"Box Jumps","sets":2,"reps":"3, low box, step down"},{"type":"drill","slug":"jump-stop-landings"},{"type":"exercise","name":"Side Plank","sets":2,"reps":"20 sec each"}]'),
  ('strength-foundations', 2, 3, 'Hinge, Lunge and Bounce', 'Week 2 (Learn the moves): hinge, split stance and first hops', 35, '[{"type":"exercise","name":"Dumbbell Romanian Deadlift","sets":3,"reps":"8, light"},{"type":"exercise","name":"Reverse Lunge","sets":2,"reps":"8 each leg"},{"type":"exercise","name":"Single-Leg Balance Reach","sets":2,"reps":"8 each leg"},{"type":"exercise","name":"Pogo Hops","sets":2,"reps":"15"},{"type":"exercise","name":"Lateral Bound & Stick","sets":2,"reps":"3 each side"},{"type":"exercise","name":"Dead Bug (Contralateral)","sets":2,"reps":"8 each side"}]'),
  ('strength-foundations', 3, 1, 'Squat With a Light Load', 'Week 3 (Build): add a light load if last week felt smooth', 40, '[{"type":"note","text":"Add weight only if every rep last week looked the same. Pick a dumbbell or kettlebell you could lift 15 times, and still stop with 2 or 3 reps left."},{"type":"exercise","name":"Goblet Squat","sets":3,"reps":"8, light dumbbell"},{"type":"exercise","name":"Dumbbell Step-Ups","sets":2,"reps":"6 each leg"},{"type":"exercise","name":"Single-Leg Hamstring Bridge","sets":2,"reps":"8 each leg"},{"type":"exercise","name":"Hollow Body Hold","sets":2,"reps":"15 sec"},{"type":"exercise","name":"Tibialis Raises","sets":2,"reps":"12"}]'),
  ('strength-foundations', 3, 2, 'Upper Body Strength', 'Week 3 (Build): push, pull and healthy shoulders', 35, '[{"type":"exercise","name":"Push-Ups (Tempo)","sets":3,"reps":"8"},{"type":"exercise","name":"Single-Arm Dumbbell Row","sets":3,"reps":"8 each arm"},{"type":"exercise","name":"Plank Shoulder Taps","sets":2,"reps":"8 each side"},{"type":"exercise","name":"Prone Y-T-W Raises","sets":2,"reps":"6 each"},{"type":"exercise","name":"Box Jumps","sets":3,"reps":"3, low box"},{"type":"exercise","name":"Snap Downs","sets":2,"reps":"5"}]'),
  ('strength-foundations', 3, 3, 'Athletic Strength', 'Week 3 (Build): single-leg strength and jumping for distance', 40, '[{"type":"exercise","name":"Dumbbell Romanian Deadlift","sets":3,"reps":"8"},{"type":"exercise","name":"Bulgarian Split Squat","sets":2,"reps":"6 each leg, bodyweight"},{"type":"exercise","name":"Lateral Lunge","sets":2,"reps":"8 each side"},{"type":"exercise","name":"Broad Jump","sets":3,"reps":"3, stick each landing"},{"type":"exercise","name":"Lateral Bound & Stick","sets":3,"reps":"3 each side"},{"type":"exercise","name":"Side Plank","sets":2,"reps":"25 sec each"}]'),
  ('strength-foundations', 4, 1, 'Strength Circuit', 'Week 4 (Build and retest): the same moves, done well', 40, '[{"type":"exercise","name":"Goblet Squat","sets":3,"reps":"10"},{"type":"exercise","name":"Dumbbell Step-Ups","sets":3,"reps":"6 each leg"},{"type":"exercise","name":"Single-Leg Hamstring Bridge","sets":3,"reps":"8 each leg"},{"type":"exercise","name":"Hollow Body Hold","sets":3,"reps":"20 sec"},{"type":"exercise","name":"Tibialis Raises","sets":2,"reps":"15"},{"type":"exercise","name":"Front Plank","sets":2,"reps":"30 sec"}]'),
  ('strength-foundations', 4, 2, 'Upper Body and Landings', 'Week 4 (Build and retest): upper body and quiet landings', 35, '[{"type":"exercise","name":"Push-Ups (Tempo)","sets":3,"reps":"8"},{"type":"exercise","name":"Single-Arm Dumbbell Row","sets":3,"reps":"10 each arm"},{"type":"exercise","name":"Plank Shoulder Taps","sets":2,"reps":"10 each side"},{"type":"exercise","name":"Prone Y-T-W Raises","sets":2,"reps":"8 each"},{"type":"exercise","name":"Box Jumps","sets":3,"reps":"3"},{"type":"exercise","name":"Snap Downs","sets":2,"reps":"5"}]'),
  ('strength-foundations', 4, 3, 'Retest Day', 'Week 4 (Build and retest): see how far you have come', 35, '[{"type":"note","text":"Warm up 8 minutes first: easy jog, skips, side shuffles and leg swings."},{"type":"test","test_type":"standing_broad_jump"},{"type":"test","test_type":"lane_agility"},{"type":"exercise","name":"Goblet Squat","sets":2,"reps":"8"},{"type":"exercise","name":"Glute Bridge","sets":2,"reps":"12"},{"type":"exercise","name":"World''s Greatest Stretch","sets":2,"reps":"5 each side"},{"type":"note","text":"Compare with week 1. Keep two of these sessions a week going alongside practice, or move on to Speed and Agility."}]'),

  ('speed-and-agility', 1, 1, 'Baseline Testing', 'Week 1 (Foundation): test your speed and agility', 40, '[{"type":"note","text":"Warm up 10 minutes first: jog, skips, side shuffles, carioca and 3 build-up runs."},{"type":"note","text":"Aged 13 to 15 or new to jumping drills? Do Basketball Strength Foundations first."},{"type":"test","test_type":"pro_agility_5_10_5"},{"type":"test","test_type":"lane_agility"},{"type":"test","test_type":"sprint_three_quarter"},{"type":"note","text":"Two tries at each test with 2 to 3 minutes of rest between them. Your best try counts."},{"type":"exercise","name":"Pogo Hops","sets":2,"reps":"15"},{"type":"exercise","name":"Dead Bug (Contralateral)","sets":2,"reps":"8 each side"}]'),
  ('speed-and-agility', 1, 2, 'Lateral Base', 'Week 1 (Foundation): stance, slides and lateral landings', 35, '[{"type":"drill","slug":"defensive-stance-holds"},{"type":"drill","slug":"lane-slides"},{"type":"exercise","name":"Lateral Bound & Stick","sets":3,"reps":"3 each side"},{"type":"exercise","name":"Lateral Lunge","sets":2,"reps":"6 each side"},{"type":"exercise","name":"Copenhagen Plank","sets":2,"reps":"15 sec each, knee on the bench"},{"type":"study","topic_slug":"defense-rotations"}]'),
  ('speed-and-agility', 1, 3, 'Stop Before You Go', 'Week 1 (Foundation): deceleration and cutting mechanics', 35, '[{"type":"note","text":"Learn to stop before you learn to go fast: hips low, short choppy steps into every cut, outside foot planted under your hip."},{"type":"exercise","name":"Snap Downs","sets":3,"reps":"4"},{"type":"drill","slug":"jump-stop-landings"},{"type":"drill","slug":"lane-line-touches"},{"type":"exercise","name":"Bulgarian Split Squat","sets":2,"reps":"6 each leg"},{"type":"exercise","name":"Single-Leg Romanian Deadlift","sets":2,"reps":"6 each leg"}]'),
  ('speed-and-agility', 2, 1, 'First Step', 'Week 2 (Foundation): acceleration from a defensive stance', 40, '[{"type":"note","text":"Warm up 10 minutes first: jog, skips, side shuffles, carioca and 3 build-up runs."},{"type":"note","text":"Starts: 6 x 10 metres from a defensive stance. Push the ground behind you, stay low for the first 3 steps and walk back to rest."},{"type":"exercise","name":"Broad Jump","sets":3,"reps":"3"},{"type":"exercise","name":"Dumbbell Step-Ups","sets":3,"reps":"6 each leg"},{"type":"exercise","name":"Single-Leg Calf Raises","sets":2,"reps":"12 each"},{"type":"exercise","name":"Front Plank","sets":2,"reps":"30 sec"}]'),
  ('speed-and-agility', 2, 2, 'Lateral Power', 'Week 2 (Foundation): push off the outside leg', 35, '[{"type":"drill","slug":"zig-zag-slides","note":"No cones? Use shoes or water bottles."},{"type":"exercise","name":"Lateral Bound & Stick","sets":3,"reps":"4 each side"},{"type":"exercise","name":"Skater Hops","sets":2,"reps":"5 each side"},{"type":"exercise","name":"Lateral Lunge","sets":3,"reps":"6 each side"},{"type":"exercise","name":"Copenhagen Plank","sets":2,"reps":"20 sec each"}]'),
  ('speed-and-agility', 2, 3, 'Change of Direction', 'Week 2 (Foundation): plant, cut and go', 40, '[{"type":"drill","slug":"box-drill"},{"type":"drill","slug":"lane-line-touches"},{"type":"exercise","name":"Single-Leg Lateral Line Hops","sets":2,"reps":"10 each leg"},{"type":"exercise","name":"Bulgarian Split Squat","sets":3,"reps":"6 each leg"},{"type":"exercise","name":"Nordic Hamstring Curl","sets":2,"reps":"3"},{"type":"study","topic_slug":"transition"}]'),
  ('speed-and-agility', 3, 1, 'Acceleration Power', 'Week 3 (Build): more starts, more power', 45, '[{"type":"note","text":"Warm up 10 minutes first: jog, skips, side shuffles, carioca and 3 build-up runs."},{"type":"exercise","name":"Broad Jump","sets":4,"reps":"3"},{"type":"note","text":"Starts: 8 x 10 metres, 4 from a defensive stance and 4 from a drop step. Walk back to rest."},{"type":"exercise","name":"Alternate-Leg Bounds","sets":3,"reps":"4 each leg"},{"type":"exercise","name":"Kettlebell Swing","sets":3,"reps":"8"},{"type":"exercise","name":"Single-Leg Calf Raises","sets":3,"reps":"12 each"}]'),
  ('speed-and-agility', 3, 2, 'Slide and Sprint', 'Week 3 (Build): lateral speed into a sprint', 40, '[{"type":"drill","slug":"slide-turn-sprint"},{"type":"drill","slug":"defensive-slide-intervals"},{"type":"exercise","name":"Lateral Bound & Stick","sets":3,"reps":"5 each side"},{"type":"exercise","name":"Skater Hops","sets":3,"reps":"6 each side"},{"type":"exercise","name":"Copenhagen Plank","sets":3,"reps":"20 sec each"}]'),
  ('speed-and-agility', 3, 3, 'Reactive Cuts', 'Week 3 (Build): quick feet and sharp cuts', 40, '[{"type":"drill","slug":"box-drill"},{"type":"exercise","name":"5-10-5 Pro Agility Shuttle","sets":4,"reps":"1 rep, full rest, alternate the starting side"},{"type":"exercise","name":"Single-Leg Lateral Line Hops","sets":3,"reps":"10 each leg"},{"type":"exercise","name":"Single-Leg Romanian Deadlift","sets":3,"reps":"6 each leg"},{"type":"exercise","name":"Nordic Hamstring Curl","sets":3,"reps":"3"},{"type":"study","topic_slug":"spacing-off-ball"}]'),
  ('speed-and-agility', 4, 1, 'Acceleration Power', 'Week 4 (Build): longer starts and bigger bounds', 45, '[{"type":"note","text":"Warm up 10 minutes first: jog, skips, side shuffles, carioca and 3 build-up runs."},{"type":"exercise","name":"Broad Jump","sets":4,"reps":"3"},{"type":"note","text":"Sprints: 8 x 15 metres, 4 from a defensive stance and 4 from a backpedal and turn. Walk back to rest."},{"type":"exercise","name":"Alternate-Leg Bounds","sets":3,"reps":"5 each leg"},{"type":"exercise","name":"Kettlebell Swing","sets":3,"reps":"10"},{"type":"exercise","name":"Bulgarian Split Squat","sets":3,"reps":"8 each leg"},{"type":"exercise","name":"Eccentric Heel Drops","sets":2,"reps":"10"}]'),
  ('speed-and-agility', 4, 2, 'Defensive Quickness', 'Week 4 (Build): slides, help and recover', 40, '[{"type":"drill","slug":"slide-turn-sprint"},{"type":"drill","slug":"help-and-recover"},{"type":"exercise","name":"Skater Hops","sets":3,"reps":"6 each side"},{"type":"exercise","name":"Lateral Lunge","sets":3,"reps":"8 each side"},{"type":"exercise","name":"Copenhagen Plank","sets":3,"reps":"25 sec each"}]'),
  ('speed-and-agility', 4, 3, 'Cut and Go', 'Week 4 (Build): change direction at full speed', 40, '[{"type":"drill","slug":"box-drill"},{"type":"exercise","name":"5-10-5 Pro Agility Shuttle","sets":5,"reps":"1 rep, full rest"},{"type":"exercise","name":"Single-Leg Lateral Line Hops","sets":3,"reps":"12 each leg"},{"type":"exercise","name":"Single-Leg Box Jump","sets":3,"reps":"3 each leg, low box"},{"type":"exercise","name":"Nordic Hamstring Curl","sets":3,"reps":"4"},{"type":"study","topic_slug":"film-study"}]'),
  ('speed-and-agility', 5, 1, 'Full-Speed Starts', 'Week 5 (Peak speed): fewer reps, all-out speed', 40, '[{"type":"note","text":"Warm up 10 minutes first: jog, skips, side shuffles, carioca and 3 build-up runs."},{"type":"exercise","name":"Hurdle Hops","sets":3,"reps":"4, low hurdles"},{"type":"exercise","name":"Broad Jump","sets":3,"reps":"3"},{"type":"note","text":"Sprints: 6 x 20 metres at full speed with a full walk back. Time one if someone can hold a phone."},{"type":"exercise","name":"Kettlebell Swing","sets":3,"reps":"8"},{"type":"exercise","name":"Single-Leg Calf Raises","sets":3,"reps":"10 each"}]'),
  ('speed-and-agility', 5, 2, 'Game-Speed Lateral', 'Week 5 (Peak speed): closeouts and slides at full speed', 40, '[{"type":"drill","slug":"closeout-sprint-series"},{"type":"drill","slug":"slide-turn-sprint"},{"type":"exercise","name":"Lateral Bound & Stick","sets":3,"reps":"4 each side"},{"type":"exercise","name":"Skater Hops","sets":3,"reps":"5 each side"},{"type":"exercise","name":"Pallof Press","sets":2,"reps":"10 each side"}]'),
  ('speed-and-agility', 5, 3, 'Agility With the Ball', 'Week 5 (Peak speed): cuts and changes of direction with the ball', 40, '[{"type":"drill","slug":"zig-zag-change-of-direction"},{"type":"exercise","name":"5-10-5 Pro Agility Shuttle","sets":4,"reps":"1 rep, full rest"},{"type":"exercise","name":"Single-Leg Box Jump","sets":3,"reps":"3 each leg"},{"type":"exercise","name":"Nordic Hamstring Curl","sets":3,"reps":"4"},{"type":"note","text":"Speed work only counts when you are fresh. Stop a set the moment you start slowing down."}]'),
  ('speed-and-agility', 6, 1, 'Taper: Stay Fast', 'Week 6 (Taper and retest): half the volume, full speed', 25, '[{"type":"note","text":"Taper week: about half the volume, full intent. Finish every session feeling fresher than when you started."},{"type":"exercise","name":"Pogo Hops","sets":2,"reps":"10"},{"type":"exercise","name":"Broad Jump","sets":2,"reps":"3"},{"type":"note","text":"Starts: 4 x 10 metres from a defensive stance, full rest."},{"type":"exercise","name":"Lateral Bound & Stick","sets":2,"reps":"3 each side"}]'),
  ('speed-and-agility', 6, 2, 'Taper: Prime the Legs', 'Week 6 (Taper and retest): half the volume, full speed', 25, '[{"type":"drill","slug":"lane-slides"},{"type":"exercise","name":"Skater Hops","sets":2,"reps":"4 each side"},{"type":"exercise","name":"5-10-5 Pro Agility Shuttle","sets":2,"reps":"1 rep, full speed"},{"type":"exercise","name":"World''s Greatest Stretch","sets":2,"reps":"5 each side"},{"type":"exercise","name":"Couch Stretch (Hip Flexor / Quad)","sets":2,"reps":"45 sec each"}]'),
  ('speed-and-agility', 6, 3, 'Retest Day', 'Week 6 (Taper and retest): retest all three', 35, '[{"type":"note","text":"Warm up 10 minutes first: jog, skips, side shuffles, carioca and 3 build-up runs."},{"type":"test","test_type":"pro_agility_5_10_5"},{"type":"test","test_type":"lane_agility"},{"type":"test","test_type":"sprint_three_quarter"},{"type":"note","text":"Compare with week 1. Taking 0.1 to 0.3 seconds off your 5-10-5 in six weeks is real progress. Keep one speed session a week going in the season to hold on to it."}]'),

  ('lockdown-defender', 1, 1, 'Stance and Slides', 'Week 1 (Foundation): a low stance you can hold', 35, '[{"type":"note","text":"Warm up 8 minutes first: jog, side shuffles, carioca and leg swings."},{"type":"test","test_type":"lane_agility"},{"type":"drill","slug":"defensive-stance-holds"},{"type":"drill","slug":"lane-slides"},{"type":"drill","slug":"zig-zag-slides","note":"No cones? Use shoes or water bottles."},{"type":"exercise","name":"Wall Sit","sets":2,"reps":"30 sec"},{"type":"note","text":"Target by week 4: hold a low stance for 45 seconds without standing up."}]'),
  ('lockdown-defender', 1, 2, 'Closeout Basics', 'Week 1 (Foundation): close out under control', 35, '[{"type":"drill","slug":"closeout-fundamentals"},{"type":"drill","slug":"help-and-recover"},{"type":"drill","slug":"toss-rebound-chin"},{"type":"exercise","name":"Lateral Band Walk","sets":2,"reps":"10 each way"},{"type":"study","topic_slug":"defense-rotations"}]'),
  ('lockdown-defender', 1, 3, 'Lateral Strength', 'Week 1 (Foundation): legs and hips for staying low', 35, '[{"type":"exercise","name":"Goblet Squat","sets":3,"reps":"8"},{"type":"exercise","name":"Lateral Lunge","sets":3,"reps":"6 each side"},{"type":"exercise","name":"Lateral Bound & Stick","sets":3,"reps":"3 each side"},{"type":"exercise","name":"Copenhagen Plank","sets":2,"reps":"15 sec each, knee on the bench"},{"type":"exercise","name":"Side Plank","sets":2,"reps":"20 sec each"},{"type":"drill","slug":"defensive-slide-intervals"}]'),
  ('lockdown-defender', 2, 1, 'Slide, Turn, Sprint', 'Week 2 (Build): open the hips and recover', 40, '[{"type":"drill","slug":"defensive-stance-holds","note":"Hold 40 seconds each set"},{"type":"drill","slug":"zig-zag-slides"},{"type":"drill","slug":"slide-turn-sprint"},{"type":"drill","slug":"mirror-drill","note":"Partner drill. On your own? Do another round of Zig-Zag Slides."},{"type":"exercise","name":"Wall Sit","sets":2,"reps":"40 sec"}]'),
  ('lockdown-defender', 2, 2, 'Closeouts and Contests', 'Week 2 (Build): contest without fouling', 40, '[{"type":"drill","slug":"closeout-fundamentals"},{"type":"drill","slug":"closeout-contest-reads","note":"Partner drill. On your own? Do Closeout Fundamentals again at full speed."},{"type":"drill","slug":"help-and-recover"},{"type":"drill","slug":"superman-rebounding"},{"type":"study","topic_slug":"rebounding"}]'),
  ('lockdown-defender', 2, 3, 'Lateral Power', 'Week 2 (Build): push off and stick the landing', 40, '[{"type":"exercise","name":"Lateral Lunge","sets":3,"reps":"8 each side"},{"type":"exercise","name":"Bulgarian Split Squat","sets":3,"reps":"6 each leg"},{"type":"exercise","name":"Skater Hops","sets":3,"reps":"4 each side"},{"type":"exercise","name":"Copenhagen Plank","sets":3,"reps":"20 sec each"},{"type":"drill","slug":"defensive-slide-intervals"}]'),
