  ('clutch-free-throws', 3, 3, 'One-and-One', 'Week 3 (Pressure): the second shot only counts if the first goes in', 30, '[{"type":"drill","slug":"free-throw-routine-builder"},{"type":"drill","slug":"tired-legs-free-throws"},{"type":"note","text":"Finish with a one-and-one game: shoot one free throw, and only shoot the second if you make the first. Play 10 rounds, score out of 20 and write it down."},{"type":"study","topic_slug":"game-situations"}]'),
  ('clutch-free-throws', 4, 1, 'Game-Winner Shots', 'Week 4 (Clutch): last-shot scenarios', 40, '[{"type":"drill","slug":"game-winner-countdown"},{"type":"drill","slug":"free-throw-pressure-ladder"},{"type":"drill","slug":"thirty-one"}]'),
  ('clutch-free-throws', 4, 2, 'Clutch Free Throws', 'Week 4 (Clutch): two shots with the game on the line', 35, '[{"type":"drill","slug":"tired-legs-free-throws"},{"type":"drill","slug":"ten-in-a-row-free-throws"},{"type":"note","text":"Finish with this game: down 1, no time left, two shots. Play 10 rounds, and a round only counts as a win if you make both. Rest 30 seconds between rounds and count your wins."}]'),
  ('clutch-free-throws', 4, 3, 'Retest', 'Week 4 (Clutch): measure your progress', 35, '[{"type":"drill","slug":"form-shooting-one-hand"},{"type":"note","text":"Shoot 50 free throws with your routine. Compare with week 1: 5 or more extra makes is a big jump."},{"type":"drill","slug":"free-throw-pressure-ladder"},{"type":"study","topic_slug":"mental-game"}]'),

  ('back-from-a-break', 1, 1, 'Touch and Rhythm', 'Week 1 (Ease in): find your shot again', 35, '[{"type":"note","text":"Go at about 70 percent this week. Finish every session feeling like you could do more."},{"type":"drill","slug":"form-shooting-one-hand"},{"type":"drill","slug":"mikan-drill"},{"type":"drill","slug":"five-spot-midrange","note":"Log your makes. You will beat this in week 2."},{"type":"drill","slug":"free-throw-routine-builder"},{"type":"exercise","name":"World''s Greatest Stretch","sets":2,"reps":"5 each side"}]'),
  ('back-from-a-break', 1, 2, 'Handle and Layups', 'Week 1 (Ease in): ball control and finishing with both hands', 35, '[{"type":"drill","slug":"ball-wraps"},{"type":"drill","slug":"pound-dribble-series"},{"type":"drill","slug":"stationary-crossover"},{"type":"drill","slug":"power-layup-series"},{"type":"drill","slug":"weak-hand-layups"},{"type":"exercise","name":"Jump Rope","sets":3,"reps":"45 sec"}]'),
  ('back-from-a-break', 1, 3, 'Legs and Lungs', 'Week 1 (Ease in): easy strength and conditioning', 35, '[{"type":"exercise","name":"Goblet Squat","sets":2,"reps":"8"},{"type":"exercise","name":"Reverse Lunge","sets":2,"reps":"6 each leg"},{"type":"exercise","name":"Push-Ups (Tempo)","sets":2,"reps":"8"},{"type":"exercise","name":"Front Plank","sets":2,"reps":"30 sec"},{"type":"drill","slug":"full-court-speed-dribble"},{"type":"exercise","name":"Full-Court Sprints","sets":6,"reps":"1 length at 70 percent, walk back"}]'),
  ('back-from-a-break', 2, 1, 'Shooting Volume', 'Week 2 (Ramp up): more shots, more range', 45, '[{"type":"drill","slug":"form-shooting-ladder"},{"type":"drill","slug":"spin-out-catch-and-shoot"},{"type":"drill","slug":"one-dribble-pull-up"},{"type":"drill","slug":"ten-in-a-row-free-throws"},{"type":"note","text":"Target: about 200 shots today. Log your makes."}]'),
  ('back-from-a-break', 2, 2, 'Moves and Finishes', 'Week 2 (Ramp up): change of pace and first jumps', 45, '[{"type":"drill","slug":"hesitation-series","note":"No cones? Use shoes or water bottles."},{"type":"drill","slug":"in-and-out-attack"},{"type":"drill","slug":"floater-series"},{"type":"drill","slug":"full-court-layup-challenge"},{"type":"exercise","name":"Box Jumps","sets":3,"reps":"3"},{"type":"exercise","name":"Lateral Bound & Stick","sets":2,"reps":"3 each side"}]'),
  ('back-from-a-break', 2, 3, 'Back Up to Speed', 'Week 2 (Ramp up): game pace, then pick your next plan', 45, '[{"type":"drill","slug":"five-spot-midrange","note":"Compare your makes with week 1"},{"type":"drill","slug":"transition-pull-ups"},{"type":"drill","slug":"defensive-slide-intervals"},{"type":"drill","slug":"tired-legs-free-throws"},{"type":"note","text":"You are back. Pick your next program: a shooting, handling or athleticism plan, or a complete off-season plan for your position."}]')
) AS v(slug, week, day, title, focus, estimated_minutes, items)
JOIN public.training_programs p ON p.slug = v.slug
ON CONFLICT (program_id, week, day) DO NOTHING;

-- =============================================================================
-- 3. FREE AND PRO
-- =============================================================================
-- New programmes are Pro (is_free defaults to false). Basketball Strength
-- Foundations is the exception, so a player on Free finds something in the
-- Athleticism group they can start. That makes four free programmes, and
-- src/lib/plans.ts says four.
--
-- Only the slugs added in this file are touched, so running it again never
-- changes the three from 00037. Running 00037 again would set Strength
-- Foundations back to Pro, because it rewrites every row: run this file after
-- it if that ever happens.
ALTER TABLE public.training_programs ADD COLUMN IF NOT EXISTS is_free boolean NOT NULL DEFAULT false;
UPDATE public.training_programs
SET is_free = (slug = 'strength-foundations')
WHERE slug IN (
  'strength-foundations', 'speed-and-agility', 'lockdown-defender', 'game-shape-conditioning',
  'injury-prevention-mobility', 'shot-creator', 'clutch-free-throws', 'back-from-a-break'
);
